-- Nexmark q15 on clink, KAFKA-SINK sink variant. Bidding statistics: COUNT
-- plus two COUNT(DISTINCT) per 10s window. The official query groups by
-- calendar day; a 10s window is the same distinct-set-per-group shape at a
-- size the harness can drain.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q15-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4001');
CREATE TABLE sink_q15 (total BIGINT, distinct_bidder BIGINT, distinct_auction BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='__OUT__');
INSERT INTO sink_q15
SELECT COUNT(*) AS total, COUNT(DISTINCT bidder) AS distinct_bidder, COUNT(DISTINCT auction) AS distinct_auction FROM bid GROUP BY TUMBLE(datetime, INTERVAL '10' SECOND);
